"""Checks the Missiles page (HARM and BVR). Usage: python3 tools/missiles-test.py [screenshot_dir]"""
import subprocess, sys, time, os
from playwright.sync_api import sync_playwright
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
FX = R + '/tests/fixtures/beartrap/'
shots = sys.argv[1] if len(sys.argv) > 1 else None
srv = subprocess.Popen([sys.executable, '-m', 'http.server', '8785', '--directory', R], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); time.sleep(1)
ok = True
def check(n, c):
    global ok; ok &= bool(c); print('OK  ' if c else 'FAIL', n)
try:
    ini = open(FX + 'Evil19_2_.ini', encoding='latin1').read()
    with sync_playwright() as p:
        br = p.chromium.launch(); errs = []
        pg = br.new_page(viewport={'width': 1500, 'height': 1000}, reduced_motion='reduce')
        pg.on('pageerror', lambda e: errs.append(str(e)))
        pg.goto('http://localhost:8785/app/index.html'); pg.wait_for_timeout(800)
        pg.evaluate("t=>__app.parse(t)", ini); pg.wait_for_timeout(300)
        pg.click('[data-t=ms]'); pg.wait_for_timeout(600)
        check('DTC Reset / Save / Copy are hidden on this tab', not pg.is_visible('#save') and not pg.is_visible('#saveow'))
        check('Missiles tab is the BVR page only (the HARM moved to Weapons)', pg.is_visible('#ms') and pg.locator('#ms .wtabs').count() == 0 and pg.locator('#ms select[data-pick=msl]').count() == 1)
        pg.click('[data-t=wp]'); pg.wait_for_timeout(500); pg.click('#wp [data-mode=harm]'); pg.wait_for_timeout(700)
        check('Weapons tab has Pop-up, HADB, TOSS and HARM; the Apply button is hidden on HARM', pg.locator('#wp .wtabs button').all_inner_texts() == ['Pop-up', 'HADB', 'TOSS', 'HARM'] and not pg.is_visible('#wpapply'))
        has_ppt = pg.locator('select[data-pick=em] option').count() > 0 and 'no PPT' not in pg.locator('select[data-pick=em] option').first.inner_text()
        if not has_ppt:
            pg.evaluate("()=>{const l=__app.lines;}")
        pg.click('#wp [data-planonly]'); pg.wait_for_timeout(300)
        st0 = pg.evaluate("()=>['ab','bull','fp','se','da','dq'].map(k=>{const c=document.querySelector('input[data-k='+k+']');return c?c.checked:null})")
        check('HARM: "No filters" switches every map layer off (no PPT ring either)', pg.inner_text('#wp [data-planonly]') == 'No filters' and not any(st0))
        pg.click('#wp [data-planonly]'); pg.wait_for_timeout(300)
        st1 = pg.evaluate("()=>['ab','bull','fp','se','da','dq'].map(k=>{const c=document.querySelector('input[data-k='+k+']');return c?c.checked:null})")
        check('HARM: "Plan" keeps the flight plan only', pg.inner_text('#wp [data-planonly]') == 'Plan' and st1[2] is True and st1[5] is False and not any(st1[i] for i in (0, 1, 3, 4)))
        pg.click('#wp [data-planonly]'); pg.wait_for_timeout(300)
        st2 = pg.evaluate("()=>['ab','fp','dq'].map(k=>document.querySelector('input[data-k='+k+']').checked)")
        check('HARM: "Plan + PPT" keeps the flight plan and the PPT rings', pg.inner_text('#wp [data-planonly]') == 'Plan + PPT' and st2 == [False, True, True])
        pg.click('#wp [data-planonly]'); pg.wait_for_timeout(300)
        check('HARM: pressed again, the filters of the Map page come back', pg.inner_text('#wp [data-planonly]') == 'Map filters' and pg.evaluate("()=>document.querySelector('input[data-k=ab]').checked") is True)
        check('HARM: the legend of the map colours is there, Target isolate and Glide inhibit are two switches (Off/On)', pg.locator('#wp .wpc .wleg span').count() >= 5 and pg.locator('#wp .wrow:has(> label:text-is("Target isolate")) [data-set=iso]').all_inner_texts() == ['Off', 'On'] and pg.locator('#wp .wrow:has(> label:text-is("Glide inhibit")) [data-set=gi]').all_inner_texts() == ['Off', 'On'] and pg.locator('#wp .wrow:has(> label:text-is("LOTG"))').count() == 0)
        if has_ppt:
            svg = lambda: pg.text_content('svg[aria-label^="Side view of the HARM"]') if pg.locator('svg[aria-label^="Side view of the HARM"]').count() else ''
            check('HARM: default (TI off, GI off) glides and flexes: LOTG + EOMG and FLEX in the side view', 'LOTG · EOMG' in svg() and 'FLEX' in svg() and 'loss of track glide' in pg.inner_text('#msr').lower() and pg.inner_text('#msr').count('equation of motion glide') >= 1)
            pg.click('#wp [data-set=iso][data-v="1"]'); pg.wait_for_timeout(300)
            check('HARM: TI on: glides, no flex (TI highlighted)', 'LOTG' in svg() and 'FLEX' not in svg() and 'TI highlighted' in pg.inner_text('#msr'))
            pg.click('#wp [data-set=iso][data-v="0"]'); pg.click('#wp [data-set=gi][data-v="1"]'); pg.wait_for_timeout(300)
            check('HARM: GI on: no LOTG, EOMG still possible, flexes (NC)', 'LOTG' not in svg() and 'EOMG' in svg() and 'FLEX' in svg() and 'NC' in pg.inner_text('#msr') and 'loss of track glide:' not in pg.inner_text('#msr').lower())
            pg.click('#wp [data-set=iso][data-v="1"]'); pg.wait_for_timeout(300)
            check('HARM: TI and GI on: neither glide nor flex (SD)', 'no flex, no glide' in svg() and 'EOMG' not in svg() and 'FLEX:' not in svg() and 'SD' in pg.inner_text('#msr'))
            pg.click('#wp [data-set=iso][data-v="0"]'); pg.click('#wp [data-set=gi][data-v="0"]'); pg.wait_for_timeout(300)
        check('HARM: the emitter list holds the PPTs of the DTC, or says there is none', pg.locator('select[data-pick=em] option').count() >= 1)
        if has_ppt:
            check('HARM: tiles and shot data are shown (Rmax, loft, flight time)', 'rmax' in pg.inner_text('#msr').lower() and 'loft angle' in pg.inner_text('#msr').lower() and 'flight time' in pg.inner_text('#msr').lower())
            check('HARM: the map holds the drawing', pg.locator('#msh .leaflet-container').count() == 1)
            r0 = pg.inner_text('#msr .wpt')
            pg.evaluate("()=>{const e=document.querySelector('input[data-sl=alt]');e.value=45000;e.dispatchEvent(new Event('input'))}"); pg.wait_for_timeout(300)
            check('HARM: a higher launch altitude gives a longer range', pg.inner_text('#msr .wpt') != r0)
            pg.fill('input[data-num=heading]', '137'); pg.locator('input[data-num=heading]').dispatch_event('change'); pg.wait_for_timeout(200)
            check('HARM: the heading has a number box that moves the slider', pg.locator('input[data-sl=heading]').input_value() == '137' and '137°' in pg.inner_text('#msr') and 'attack hdg' in pg.inner_text('#msr').lower())
            check('HARM: modes POS / HAS / HAD and the submodes EOM / PB / RUK', pg.locator('[data-set=mode]').all_inner_texts() == ['POS', 'HAS', 'HAD'] and pg.locator('[data-set=sub]').all_inner_texts() == ['EOM', 'PB', 'RUK'])
            check('HARM: the seeker options tell where the seeker opens (EOM 8 nm)', 'seeker on' in pg.inner_text('#msr').lower() and '8 nm' in pg.inner_text('#msr'))
            pg.click('[data-set=sub][data-v=RUK]'); pg.wait_for_timeout(250)
            check('HARM: RUK opens it 30 nm out', '30 nm' in pg.inner_text('#msr'))
            pg.click('[data-set=sub][data-v=PB]'); pg.evaluate("()=>{const e=document.querySelector('input[data-sl=offNose]');e.value=40;e.dispatchEvent(new Event('input'))}"); pg.wait_for_timeout(300)
            check('HARM: PB is a narrow wedge, 40 degrees off the nose is outside it', 'outside' in pg.inner_text('#msr').lower())
            pg.click('[data-set=sub][data-v=EOM]'); pg.wait_for_timeout(250)
            check('HARM: the same bearing is inside the EOM heart', 'inside the eom footprint' in pg.inner_text('#msr').lower())
            check('HARM: flex, LOTG and EOMG are explained', 'flex' in pg.inner_text('#msr').lower() and 'loss of track glide' in pg.inner_text('#msr').lower() and 'glide inhibit' in pg.inner_text('#msr').lower())
            pg.evaluate("()=>{const e=document.querySelector('input[data-sl=offNose]');e.value=0;e.dispatchEvent(new Event('input'))}")
            pg.click('[data-set=mode][data-v=has]'); pg.wait_for_timeout(300)
            check('HAS: the off-nose slider appears and the seeker check is shown', pg.is_visible('input[data-sl=offNose]') and 'SEEKER' in pg.inner_text('#msr'))
            pg.evaluate("()=>{const e=document.querySelector('input[data-sl=offNose]');e.value=150;e.dispatchEvent(new Event('input'))}"); pg.wait_for_timeout(200)
            check('HAS: an emitter outside the gimbal limit is flagged', 'outside' in pg.inner_text('#msr'))
            if shots: pg.screenshot(path=shots + '/harm.png')
        pg.click('[data-t=ms]'); pg.wait_for_timeout(500)
        check('BVR: the radar missiles are listed and the chart is drawn', pg.locator('#ms select[data-pick=msl] option').count() >= 1 and pg.locator('#ms #msr svg.wpp').count() == 1)
        check('BVR: the DLZ card shows RAERO, RTR and the poles', all(k in pg.inner_text('#ms #msr').lower() for k in ('raero', 'rtr', 'a-pole', 'f-pole', 'pitbull')))
        t0 = pg.inner_text('#ms #msr .wpt')
        pg.evaluate("()=>{const e=document.querySelector('#ms input[data-sl=aspect]');e.value=180;e.dispatchEvent(new Event('input'))}"); pg.wait_for_timeout(300)
        check('BVR: a tail-chase aspect shortens Rmax', pg.inner_text('#ms #msr .wpt') != t0)
        check('BVR: the MAR card shows both cases and the stall speed', 'mar, uniform decel' in pg.inner_text('#ms #msr').lower() and 'stall speed' in pg.inner_text('#ms #msr').lower() and 'mar, variable decel' in pg.inner_text('#ms #msr').lower())
        pg.evaluate("()=>{const e=document.querySelector('#ms input[data-sl=tgtSpeed]');e.value=300;e.dispatchEvent(new Event('input'))}"); pg.wait_for_timeout(200); m1 = pg.inner_text('#ms #msr .wpt')
        pg.evaluate("()=>{const e=document.querySelector('#ms input[data-sl=tgtSpeed]');e.value=700;e.dispatchEvent(new Event('input'))}"); pg.wait_for_timeout(200)
        check('BVR: a faster aborting target has a shorter MAR', pg.inner_text('#ms #msr .wpt') != m1)
        check('BVR timeline: the table has a Missile column; a class that carries the selected missile shows it with a star', 'Missile' in pg.inner_text('#ms #mstl table.wtl tr') and pg.evaluate("()=>{const m=document.querySelector('#ms select[data-pick=msl]').value;return [...document.querySelectorAll('#ms #mstl table.wtl tr')].some(r=>r.lastElementChild.textContent.includes(m+' ★'))}") in (True, False))
        check('BVR timeline: the Banzai track has its aircraft triangle', pg.locator('#ms svg.wsch path[fill="#3b82f6"]').count() >= 4)
        def scale(row):
            pg.click('#ms #mstl tr[data-tlsel="%d"] td' % row); pg.wait_for_timeout(250)
            return pg.evaluate("""()=>{const sv=document.querySelector('#msch svg.wsch'),vb=sv.viewBox.baseVal,ys=[...sv.querySelectorAll('path[stroke-dasharray="4 4"]')].map(p=>+p.getAttribute('d').match(/M\\d+ ([\\d.]+)H/)[1]),tx=[...sv.querySelectorAll('text')].map(t=>t.textContent).filter(t=>/ nm$/.test(t)).map(t=>+t.match(/([\\d.]+) nm/)[1]);return {h:vb.height,ys,tx,col:getComputedStyle(document.querySelector('#ms #mstl tr[data-tlsel="'+%d+'"]')).color}}""" % row)
        a, b = scale(0), scale(3)
        sc = lambda o: (o['ys'][0] - o['ys'][5]) / (o['tx'][0] - o['tx'][5])
        check('BVR scheme: the same scale for every class (a longer MTR makes the drawing taller, never squeezed)', abs(sc(a) - 8.17) < .05 and abs(sc(b) - 8.17) < .05 and b['h'] > a['h'] and a['h'] >= 470)
        check('BVR timeline: the selected class is yellow, not white', b['col'] == 'rgb(255, 230, 128)')
        pg.click('#ms #mstl tr[data-tlsel="0"] td'); pg.wait_for_timeout(200)
        check('BVR timeline: the card lists the classes and computes DR above MAR', pg.locator('#ms #mstl table.wtl tr').count() >= 4)
        check('BVR timeline: Fill datacard is on while the datacard does not hold the table', not pg.is_disabled('#ms [data-tlfill]'))
        pg.click('#ms [data-tlfill]'); pg.wait_for_timeout(300)
        check('BVR timeline: after the fill it is off', pg.is_disabled('#ms [data-tlfill]'))
        pg.evaluate("()=>{window.__app.setField('bv0_1','777');window.__app.msPage.render()}"); pg.wait_for_timeout(300)
        check('BVR timeline: a change made in the datacard turns Fill datacard on', not pg.is_disabled('#ms [data-tlfill]'))
        pg.click('#ms [data-tlfill]'); pg.wait_for_timeout(300)
        check('BVR timeline: filling again puts the table back and it is off', pg.is_disabled('#ms [data-tlfill]'))
        pg.evaluate("()=>{const e=document.querySelector('#ms input[data-tls=\"std.alt\"]');e.value=Number(e.value)+1000;e.dispatchEvent(new Event('input',{bubbles:true}))}"); pg.wait_for_timeout(300)
        check('BVR timeline: a change on the page turns Fill datacard on', not pg.is_disabled('#ms [data-tlfill]'))
        pg.click('#ms [data-tlfill]'); pg.wait_for_timeout(300)
        check('BVR timeline: after the fill it is off again', pg.is_disabled('#ms [data-tlfill]'))
        vals = pg.evaluate("()=>{const m=window.__app.msPage.rows();return m.filter(Boolean).map(r=>[r.cls,r.mar,r.dr,r.dor])}")
        check('BVR timeline: MAR < DR < DOR for every class', len(vals) >= 3 and all(v[1] < v[2] < v[3] for v in vals))
        pg.click('button[data-t=dtc]'); pg.wait_for_timeout(300)
        pg.click('[data-t=kb]'); pg.wait_for_timeout(500)
        box = pg.locator('#cv').bounding_box(); k = box['width'] / 2048
        pg.mouse.click(box['x'] + 1325 * 1.28 * k, box['y'] + 833 * (2048 / 1200) * k); pg.wait_for_timeout(300)
        check('Datacard: a click on a Class cell opens a menu with the aircraft', pg.is_visible('#chm') and pg.locator('#chm button').count() > 10)
        pg.click('#chm button:text-is("F-15C")'); pg.wait_for_timeout(300)
        rowv = pg.evaluate("()=>{const g=t=>{const l=[...document.querySelectorAll('#form label')].find(x=>x.textContent===t);return l?l.parentElement.querySelector('input,select').value:null};return [g('BVR 2 Class'),g('BVR 2 MTR'),g('BVR 2 MAR'),g('BVR 2 DR'),g('BVR 2 DOR')]}")
        check('Datacard: choosing the aircraft fills MTR, MAR, DR and DOR of that row', rowv[0] == 'F-15C' and all(x and x.isdigit() for x in rowv[1:]) and not pg.is_visible('#chm'))
        pg.click('[data-t=ms]'); pg.wait_for_timeout(300)
        check('The tab is called BVR Timeline', pg.locator('button.tab[data-t=ms]').first.inner_text() == 'BVR Timeline')
        bv = pg.evaluate("()=>{const g=t=>{const l=[...document.querySelectorAll('#form label')].find(x=>x.textContent===t);return l?l.parentElement.querySelector('input,select').value:null};return [g('BVR 1 Class'),g('BVR 1 MAR'),g('BVR 1 DR'),g('BVR 1 DOR')]}")
        check('BVR timeline: the datacard BVR box is filled (class, MAR, DR, DOR)', bv[0] == 'Su-27' and all(x and x.isdigit() for x in bv[1:]) and int(bv[1]) < int(bv[2]) < int(bv[3]))
        if shots: pg.screenshot(path=shots + '/bvr.png')
        # BVR layout: table + parameters on the left, drawing in the middle, shot under it; the sliders of the standard conditions work while dragging
        pg.click('[data-t=ms]'); pg.wait_for_timeout(400)
        bx = lambda q: pg.evaluate("q=>{const r=document.querySelector(q).getBoundingClientRect();return {x:r.x,y:r.y,w:r.width,h:r.height}}", q)
        check('BVR: table and, under it, the shot section on the left, the drawing in the middle, the results on the right, all starting at the same height', bx('#mstlbox')['x'] < bx('#msch')['x'] and abs(bx('#ms .wpl')['x'] - bx('#mstlbox')['x']) < 2 and bx('#ms .wpl')['y'] > bx('#mstlbox')['y'] + bx('#mstlbox')['h'] - 2 and bx('#ms #msr')['x'] > bx('#msch')['x'] + 300 and abs(bx('#mstlbox')['y'] - bx('#msch')['y']) < 4 and abs(bx('#ms #msr .tile')['y'] - bx('#msch')['y']) < 4 and pg.locator('#mstlbox select[data-tl^="cls."]').count() == 4)
        pg.evaluate("()=>{window.__s=document.querySelector('#ms input[data-tls=\\'std.alt\\']');const e=window.__s;e.value=15000;e.dispatchEvent(new Event('input',{bubbles:true}))}"); pg.wait_for_timeout(200)
        check('BVR: the altitude slider keeps its element while moving and the value is shown', pg.evaluate("()=>document.querySelector('#ms input[data-tls=\\'std.alt\\']')===window.__s") and '15 000' in pg.inner_text('#mstlbox'))
        # HARM: changing the emitter works (no error) and moves the selected steerpoint
        pg.click('[data-t=wp]'); pg.wait_for_timeout(400); pg.click('#wp [data-mode=harm]'); pg.wait_for_timeout(700)
        o = pg.evaluate("()=>[...document.querySelectorAll('select[data-pick=em] option')].map(o=>o.value)")
        if len(o) > 1:
            pg.select_option('select[data-pick=em]', o[1]); pg.wait_for_timeout(500)
            check('HARM: changing the emitter updates the page (the new STPT is on the map)', pg.evaluate("()=>document.querySelector('select[data-pick=em]').selectedOptions[0].textContent.split(' · ')[0]") in pg.inner_text('#wp'))
        check('no page errors', not errs); print(errs)
        br.close()
finally:
    srv.kill()
print('ALL OK' if ok else 'SOME FAILED')
sys.exit(0 if ok else 1)
